// Map ERP-specific naming to the canonical order model used by the data mart.
const items = $input.all();
const out = [];
const seen = new Set();

for (const item of items) {
  const r = item.json;
  const orderId = String(r.OrderId || r.orderId || '');
  if (!orderId || seen.has(orderId)) continue;      // de-duplicate within one run
  seen.add(orderId);

  const value = Number(r.OrderValue || 0);
  const units = Number(r.TotalUnits || 0);
  const avgPrice = Number(r.AvgUnitPrice || (units ? value / units : 0));
  const creditLimit = Number(r.CreditLimit || 0);
  const utilisation = creditLimit > 0 ? Math.round((value / creditLimit) * 100) : 0;

  out.push({ json: {
    orderId,
    orderNo: String(r.OrderNo || ''),
    customerId: String(r.CustomerId || ''),
    customerName: r.CustomerName || 'Unknown customer',
    customerEmail: r.CustomerEmail || '',
    territoryId: String(r.TerritoryId || ''),
    orderValue: Number(value.toFixed(2)),
    totalUnits: units,
    avgUnitPrice: Number(avgPrice.toFixed(2)),
    creditLimit: Number(creditLimit.toFixed(2)),
    creditUtilisationPct: utilisation,
    creditRisk: Number(r.CreditRiskFlag) === 1 || utilisation >= 90,
    erpStatus: String(r.ErpStatus || ''),
    lastModified: r.LastModified || new Date().toISOString(),
    syncedAt: new Date().toISOString(),
  }});
}

return out;

