const t = $input.first().json;
const top = Array.isArray(t.top_customers) ? t.top_customers : [];
const rows = top.map(c => `            <tr><td>${c.customer}</td><td align="right">${Number(c.total_value).toLocaleString('en-US')}</td><td align="right">${c.orders}</td></tr>`).join('\n');

return [{ json: {
