    <tr><td style="background:#f5f7fa"><b>Credit-risk orders</b></td><td>${t.credit_risk_orders}</td></tr>
  </table>
  <h3 style="margin:0 0 6px">Top customers (last 6h)</h3>
  <table cellpadding="6" cellspacing="0" border="1" style="border-collapse:collapse;border-color:#d9e2ec">
    <tr style="background:#eef2f7"><th align="left">Customer</th><th>Value</th><th>Orders</th></tr>
${rows || '            <tr><td colspan="3">No orders in window</td></tr>'}
  </table></body></html>`,
}}];

const e = $input.first().json;
return [{ json: {
  workflow: e.workflow?.name || '01 ERP Order-to-Cash Sync',
  failedNode: e.execution?.lastNodeExecuted || 'unknown',
  errorMessage: (e.execution?.error?.message || 'Unknown error').slice(0, 500),
  executionUrl: e.execution?.url || '',
